class Store{static const key='mirath_files';static Future<List<Map<String,dynamic>>> all()async{final p=await SharedPreferences.getInstance();final s=p.getString(key);if(s==null)return[];return(jsonDecode(s)as List).map((e)=>Map<String,dynamic>.from(e)).toList();}static Future<void> save(List<Map<String,dynamic>> a)async{final p=await SharedPreferences.getInstance();await p.setString(key,jsonEncode(a));}static Future<String> code()async{final a=await all();return'MM-${(a.length+1).toString().padLeft(6,'0')}';}static Future<void> add(Map<String,dynamic> x)async{final a=await all();a.add(x);await save(a);}}
