).toList(),onChanged:(v){if(v!=null)setState(()=>type=v);}),const SizedBox(height:8),DropdownButtonFormField<String>(initialValue:deal,decoration:const InputDecoration(labelText:'نوع معامله',border:OutlineInputBorder()),items:const['فروش','رهن و اجاره','اجاره','پیش‌فروش','مشارکت'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v){if(v!=null)setState(()=>deal=v);}),const SizedBox(height:8),f('title','عنوان فایل'),f('area','متراژ'),f('rooms','تعداد خواب'),f('year','سال ساخت'),f('floor','طبقه'),f('unit','واحد'),f('price','قیمت فروش'),f('deposit','رهن'),f('rent','اجاره'),f('owner','نام مالک'),f('phone','شماره مالک'),f('national','کد ملی مالک'),f('address','آدرس کامل'),f('postal','کد پستی'),f('document','شماره سند'),f('permit','جواز/پایان‌کار'),f('consultant','مشاور مسئول'),TextField(controller:c['divar'],decoration:InputDecoration(labelText:'لینک آگهی دیوار',border:const OutlineInputBorder(),suffixIcon:IconButton(onPressed:paste,icon:const Icon(Icons.content_paste)))),Row(children:[TextButton(onPressed:paste,child:const Text('Paste')),TextButton(onPressed:()=>Clipboard.setData(ClipboardData(text:c['divar']!.text)),child:const Text('کپی لینک'))]),f('description','توضیحات'),const Text('چک‌لیست فایل',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))];fields.addAll(items.map((q)=>CheckboxListTile(value:checks[q],onChanged:(v)=>setState(()=>checks[q]=v??false),title:Text(q),dense:true)));fields.add(const SizedBox(height:10));fields.add(SizedBox(height:52,child:FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save),label:const Text('ثبت و ذخیره فایل'))));return Scaffold(appBar:AppBar(title:const Text('ثبت فایل کامل ملک'),backgroundColor:navy,foregroundColor:Colors.white),body:Directionality(textDirection:TextDirection.rtl,child:ListView(padding:const EdgeInsets.all(16),children:fields));}}
